input.script:
companies = list_companies({})
first = boundary retry 2 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_contacts({ page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
contacts = fold acc = first.items for page in remaining { return acc + page }

domain_to_company = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

results = for contact in contacts {
    phone = contact.phone if contact.phone != null else ""
    digits = regex.replace(phone, "[^0-9]", "")
    e164 = if text.starts_with(phone, "+1") and text.length(phone) == 12 and regex.test(phone, "^\\+1[0-9]{10}$") {
        return phone
    } else {
        d = if text.length(digits) == 11 and text.starts_with(digits, "1") {
            return text.slice(digits, 1)
        } else if text.length(digits) == 10 {
            return digits
        } else {
            return ""
        }
        return "+1" + d if d != "" else phone
    }
    need_phone = e164 != phone and e164 != "" and regex.test(e164, "^\\+1[0-9]{10}$")

    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) == 2 else ""
    company_empty = contact.company == null or contact.company == ""
    matched = domain_to_company[domain] if domain != "" and domain in domain_to_company else null
    need_company = company_empty and matched != null

    updated = if need_phone or need_company {
        args = { id: contact.id }
        args2 = args + { phone: e164 } if need_phone else args
        args3 = args2 + { company: matched } if need_company else args2
        u = boundary retry 2 {
            return update_contact(args3)
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
        return { phone: need_phone, company: need_company }
    } else {
        return { phone: false, company: false }
    }
    return updated
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company else 0)
}

sub = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, recorded: sub.recorded }
